entries[89202] = { ["name"] = "Raptorleaf Seed", ["text"] = "Binds when picked up\nUse: Plant a Raptorleaf Seed.\n\"The raptorleaf is a carnivorous plant which is known to devour virmen, hawks and other small creatures. It dies after a single meal, releasing seeds into the air and often leaving behind the remains of its catch.\"\nSell Price:" }
